def fib(n: int) -> int:
    if n < 0:
        raise ValueError("n must be non-negative")
    def _pair(k: int) -> tuple[int, int]:
        if k == 0:
            return (0, 1)
        a, b = _pair(k >> 1)
        c = a * ((b << 1) - a)
        d = a * a + b * b
        if k & 1:
            return (d, c + d)
        else:
            return (c, d)
    return _pair(n)[0]
```

